#!/usr/bin/env node
/**
 * Tests for hooks/lib/fire-log.js and its wiring: every hook fire appends one `{ day, hook, event,
 * decision, sub }` line to `<config>/.cache/hook-fires.log`, until the log holds six distinct days.
 *
 * Each case runs in a child process with its own CLAUDE_CONFIG_DIR (a temp directory), so no case can
 * touch the real cache. NODE_TEST_CONTEXT is dropped from the child's environment: the library stays
 * silent under `node --test` so the other suites' hook runs never write the real log.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, existsSync, rmSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const LIB = join(ROOT, 'hooks', 'lib', 'fire-log.js');
const created = [];

function temp(prefix) {
  const dir = mkdtempSync(join(tmpdir(), prefix));
  created.push(dir);
  return dir;
}

process.on('exit', () => {
  for (const dir of created) {
    try { rmSync(dir, { recursive: true, force: true }); } catch { /* tmp, let the OS have it */ }
  }
});

const logOf = (config) => join(config, '.cache', 'hook-fires.log');
const linesOf = (config) => (existsSync(logOf(config)) ? readFileSync(logOf(config), 'utf8').split('\n').filter(Boolean) : []);

function env(config, extra = {}) {
  const e = { ...process.env, CLAUDE_CONFIG_DIR: config, ...extra };
  delete e.CLAUDE_HOOK_FIRE_LOG;
  delete e.NODE_TEST_CONTEXT;
  delete e.CLAUDE_DONE_CLAIM;
  return { ...e, ...extra };
}

/** `logFire(args)` in a fresh process. */
function fire(config, args, extra) {
  const r = spawnSync(process.execPath, ['-e', `require(${JSON.stringify(LIB)}).logFire(JSON.parse(process.argv[1]))`, JSON.stringify(args)], { env: env(config, extra), encoding: 'utf8' });
  assert.equal(r.status, 0, r.stderr);
}

/** A hook script run for real, its payload on stdin. `extra` overrides the child's environment; `status` is the exit code expected. */
function runHook(config, hook, payload, { cwd = temp('fire-cwd-'), extra, status = 0 } = {}) {
  const r = spawnSync(process.execPath, [join(ROOT, 'hooks', hook)], { input: JSON.stringify(payload), env: env(config, extra), cwd, encoding: 'utf8' });
  assert.equal(r.status, status, r.stderr);
  return r.stdout;
}

const localDay = () => {
  const d = new Date();
  const p = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
};

const seedDays = (config, days) => {
  mkdirSync(join(config, '.cache'), { recursive: true });
  writeFileSync(logOf(config), days.map((day) => JSON.stringify({ day, hook: 'guard-shell', event: 'PreToolUse', decision: 'silent', sub: false })).join('\n') + '\n');
};

test('given an empty log, when a hook fires, then one line with the five fields is appended', () => {
  // Given
  const config = temp('fire-cfg-');
  // When
  fire(config, { hook: 'guard-shell', event: 'PreToolUse', decision: 'deny', sub: true });
  // Then
  const lines = linesOf(config);
  assert.equal(lines.length, 1);
  assert.deepEqual(JSON.parse(lines[0]), { day: localDay(), hook: 'guard-shell', event: 'PreToolUse', decision: 'deny', sub: true });
});

test('given a log with six distinct days, when a hook fires on a seventh, then nothing is appended', () => {
  // Given
  const config = temp('fire-cfg-');
  seedDays(config, ['2020-01-01', '2020-01-02', '2020-01-03', '2020-01-04', '2020-01-05', '2020-01-06']);
  const before = readFileSync(logOf(config), 'utf8');
  // When
  fire(config, { hook: 'guard-shell', event: 'PreToolUse', decision: 'silent', sub: false });
  // Then
  assert.equal(readFileSync(logOf(config), 'utf8'), before);
});

test('given a log with six distinct days, when a hook fires on the sixth day again, then the line is appended', () => {
  // Given
  const config = temp('fire-cfg-');
  seedDays(config, ['2020-01-01', '2020-01-02', '2020-01-03', '2020-01-04', '2020-01-05', localDay()]);
  // When
  fire(config, { hook: 'guard-shell', event: 'PreToolUse', decision: 'silent', sub: false });
  // Then
  assert.equal(linesOf(config).length, 7);
});

test('given an unwritable log, when a hook fires, then the hook\'s decision is unchanged', () => {
  // Given: a directory where the log file should be, so every append fails
  const payload = { hook_event_name: 'PreToolUse', tool_name: 'Agent', tool_input: { prompt: 'x' } };
  const healthy = runHook(temp('fire-cfg-'), 'agent-guard.js', payload);
  const broken = temp('fire-cfg-');
  mkdirSync(logOf(broken), { recursive: true });
  // When
  const out = runHook(broken, 'agent-guard.js', payload);
  // Then
  assert.match(out, /"permissionDecision":"deny"/);
  assert.equal(out, healthy);
});

test('given an unwritable log, when a context hook and a silent hook fire, then their stdout is unchanged', () => {
  // Given
  const cwd = temp('fire-cwd-');
  const cases = [
    ['subagent-lang.js', { hook_event_name: 'SubagentStart', agent_type: 'Explore', cwd }],
    ['read-guard.js', { hook_event_name: 'PreToolUse', tool_input: { file_path: 'missing.txt' } }],
  ];
  for (const [hook, payload] of cases) {
    const healthy = runHook(temp('fire-cfg-'), hook, payload, { cwd });
    const broken = temp('fire-cfg-');
    mkdirSync(logOf(broken), { recursive: true });
    // When
    const out = runHook(broken, hook, payload, { cwd });
    // Then
    assert.equal(out, healthy, hook);
  }
});

test('given the opt-out env CLAUDE_HOOK_FIRE_LOG=0, when a hook fires, then nothing is appended', () => {
  // Given
  const config = temp('fire-cfg-');
  // When
  fire(config, { hook: 'guard-shell', event: 'PreToolUse', decision: 'silent', sub: false }, { CLAUDE_HOOK_FIRE_LOG: '0' });
  // Then
  assert.deepEqual(linesOf(config), []);
});

test('given a run under node --test, when a hook fires, then nothing is appended', () => {
  // Given
  const config = temp('fire-cfg-');
  // When
  fire(config, { hook: 'guard-shell', event: 'PreToolUse', decision: 'silent', sub: false }, { NODE_TEST_CONTEXT: 'child-v8' });
  // Then
  assert.deepEqual(linesOf(config), []);
});

test('given a log of six days, when a seventh day is refused, then the closed sentinel is written', () => {
  // Given
  const config = temp('fire-cfg-');
  seedDays(config, ['2020-01-01', '2020-01-02', '2020-01-03', '2020-01-04', '2020-01-05', '2020-01-06']);
  // When
  fire(config, { hook: 'guard-shell', event: 'PreToolUse', decision: 'silent', sub: false });
  // Then
  assert.ok(existsSync(join(config, '.cache', 'hook-fires.closed')));
});

test('given the closed sentinel, when a hook fires, then nothing is appended even though the log holds one day', () => {
  // Given
  const config = temp('fire-cfg-');
  seedDays(config, ['2020-01-01']);
  writeFileSync(join(config, '.cache', 'hook-fires.closed'), '');
  // When
  fire(config, { hook: 'guard-shell', event: 'PreToolUse', decision: 'silent', sub: false });
  // Then
  assert.equal(linesOf(config).length, 1);
});

test('given a decision hook, when it denies and when it stays silent, then each fire is one line with its decision and sub flag', () => {
  // Given
  const config = temp('fire-cfg-');
  const base = { hook_event_name: 'PreToolUse', tool_name: 'Agent' };
  // When
  runHook(config, 'agent-guard.js', { ...base, tool_input: { prompt: 'x' } });
  runHook(config, 'agent-guard.js', { ...base, agent_id: 'a1', tool_input: { subagent_type: 'Explore', prompt: 'x' } });
  // Then
  const [first, second] = linesOf(config).map((l) => JSON.parse(l));
  assert.equal(linesOf(config).length, 2);
  assert.deepEqual([first.hook, first.event, first.decision, first.sub], ['agent-guard', 'PreToolUse', 'deny', false]);
  assert.deepEqual([second.hook, second.decision, second.sub], ['agent-guard', 'silent', true]);
});

for (const [hook, event, payload] of [
  ['read-guard.js', 'PreToolUse', { hook_event_name: 'PreToolUse', tool_input: { file_path: 'missing.txt' } }],
  ['screenshot-guard.js', 'PreToolUse', { hook_event_name: 'PreToolUse', tool_name: 'x__browser_screenshot', tool_input: {} }],
  ['guard-shell.js', 'PreToolUse', { hook_event_name: 'PreToolUse', tool_name: 'Bash', tool_input: { command: 'echo hi' } }],
  ['secret-scan.js', 'PreToolUse', { hook_event_name: 'PreToolUse', tool_name: 'Write', tool_input: { file_path: 'a.txt', content: 'hello' } }],
  ['done-claim.js', 'Stop', { hook_event_name: 'Stop' }],
  ['format-on-edit.js', 'PostToolUse', { hook_event_name: 'PostToolUse', tool_input: { file_path: 'notes.md' } }],
  ['session-brief.js', 'SessionStart', { hook_event_name: 'SessionStart', source: 'startup' }],
  ['workspace-context.js', 'SessionStart', { hook_event_name: 'SessionStart', source: 'startup' }],
  ['worklog-pending.js', 'SessionStart', { hook_event_name: 'SessionStart', source: 'startup' }],
  ['subagent-lang.js', 'SubagentStart', { hook_event_name: 'SubagentStart', agent_type: 'Explore' }],
]) {
  test(`given the ${hook} hook, when it fires, then exactly one ${event} line is logged`, () => {
    // Given
    const config = temp('fire-cfg-');
    // When
    runHook(config, hook, payload);
    // Then
    const lines = linesOf(config).map((l) => JSON.parse(l));
    assert.equal(lines.length, 1, JSON.stringify(lines));
    assert.equal(lines[0].hook, hook.replace(/\.js$/, ''));
    assert.equal(lines[0].event, event);
  });
}

/** The one line a hook left, parsed. */
const onlyLine = (config) => {
  const lines = linesOf(config).map((l) => JSON.parse(l));
  assert.equal(lines.length, 1, JSON.stringify(lines));
  return lines[0];
};

test('given a write carrying a credential, when secret-scan denies it, then one deny line is logged', () => {
  // Given
  const config = temp('fire-cfg-');
  const content = `token ${'ghp_'}${'aB3dE5gH7jK9mN1pQ3sT5vX7zA9cE1gI3kM5'}`;
  // When
  runHook(config, 'secret-scan.js', { hook_event_name: 'PreToolUse', tool_name: 'Write', tool_input: { file_path: 'a.txt', content } });
  // Then
  assert.equal(onlyLine(config).decision, 'deny');
});

test('given a turn that edited and claims success without proof, when done-claim blocks it, then one block line is logged', () => {
  // Given
  const config = temp('fire-cfg-');
  const dir = temp('fire-cwd-');
  const transcript = join(dir, 't.jsonl');
  const entries = [
    { type: 'user', message: { role: 'user', content: 'fix it' } },
    { type: 'assistant', message: { role: 'assistant', content: [{ type: 'tool_use', id: 't', name: 'Edit', input: {} }] } },
    { type: 'user', message: { role: 'user', content: [{ type: 'tool_result', tool_use_id: 't', content: 'ok' }] } },
  ];
  writeFileSync(transcript, entries.map((e) => JSON.stringify(e)).join('\n') + '\n');
  // When
  const out = runHook(config, 'done-claim.js', { hook_event_name: 'Stop', transcript_path: transcript, cwd: dir, last_assistant_message: 'Fixed, done.' }, { extra: { CLAUDE_DONE_CLAIM: '1' } });
  // Then
  assert.match(out, /"decision":"block"/);
  assert.equal(onlyLine(config).decision, 'block');
});

test('given a destructive command, when guard-shell asks, then one ask line is logged', () => {
  // Given
  const config = temp('fire-cfg-');
  // When
  const out = runHook(config, 'guard-shell.js', { hook_event_name: 'PreToolUse', tool_name: 'Bash', tool_input: { command: 'docker compose down -v' } });
  // Then
  assert.match(out, /"permissionDecision":"ask"/);
  assert.equal(onlyLine(config).decision, 'ask');
});

test('given a WorktreeRemove of a path that is no worktree, when worktree-root fails, then one WorktreeRemove line is logged', () => {
  // Given
  const config = temp('fire-cfg-');
  const nowhere = temp('fire-nowhere-');
  // When
  runHook(config, 'worktree-root.js', { hook_event_name: 'WorktreeRemove', worktree_path: nowhere }, { cwd: nowhere, status: 1 });
  // Then
  const line = onlyLine(config);
  assert.deepEqual([line.hook, line.event], ['worktree-root', 'WorktreeRemove']);
});

test('given CLAUDE_DONE_CLAIM unset, when done-claim exits at once for a subagent, then the line says sub', () => {
  // Given
  const config = temp('fire-cfg-');
  // When
  runHook(config, 'done-claim.js', { hook_event_name: 'Stop', agent_id: 'a1' });
  // Then
  assert.equal(onlyLine(config).sub, true);
});
